-- Partial index: only rows matching hot predicate are indexed
-- Shrinks index size and write amplification dramatically
CREATE INDEX CONCURRENTLY IF NOT EXISTS {{index_name}}
  ON {{table_name}} ({{lookup_column}})
  WHERE {{filter_column}} = '{{filter_value}}';

-- Planner only uses partial index when WHERE clause includes the predicate
EXPLAIN ANALYZE
SELECT *
FROM {{table_name}}
WHERE {{filter_column}} = '{{filter_value}}'
  AND {{lookup_column}} = $1;
